+unsigned int
+sanitize_usb_max_packet_size(guint8 ep_type, usb_speed_t speed,
+                             unsigned int max_packet_size)
+{
+    unsigned int sanitized = max_packet_size;
+    switch (speed) {
+    case USB_SPEED_LOW:
+        switch (ep_type) {
+            case ENDPOINT_TYPE_CONTROL:
+                /* 8 is the only allowed value */
+                sanitized = 8;
+                break;
+            case ENDPOINT_TYPE_INTERRUPT:
+                if (max_packet_size > 8)
+                    sanitized = 8;
+                break;
+            default:
+                /* Not allowed */
+                break;
+        }
+        break;
+    case USB_SPEED_FULL:
+        switch (ep_type) {
+        case ENDPOINT_TYPE_CONTROL:
+        case ENDPOINT_TYPE_BULK:
+            /* Allowed values are: 8, 16, 32 and 64 */
+            if (max_packet_size > 32)
+                sanitized = 64;
+            else if (max_packet_size > 16)
+                sanitized = 32;
+            else if (max_packet_size > 8)
+                sanitized = 16;
+            else
+                sanitized = 8;
+            break;
+        case ENDPOINT_TYPE_INTERRUPT:
+            if (max_packet_size > 64)
+                sanitized = 64;
+            break;
+        case ENDPOINT_TYPE_ISOCHRONOUS:
+            if (max_packet_size > 1023)
+                sanitized = 1023;
+            break;
+        default:
+            break;
+        }
+        break;
+    case USB_SPEED_HIGH:
+        switch (ep_type) {
+        case ENDPOINT_TYPE_CONTROL:
+            /* 64 is the only allowed value */
+            sanitized = 64;
+            break;
+        case ENDPOINT_TYPE_BULK:
+            /* 512 is the only allowed value */
+            sanitized = 512;
+            break;
+        case ENDPOINT_TYPE_INTERRUPT:
+        case ENDPOINT_TYPE_ISOCHRONOUS:
+            if (max_packet_size > 1024)
+                sanitized = 1024;
+            break;
+        default:
+            break;
+        }
+        break;
+    case USB_SPEED_UNKNOWN:
+    default:
+        break;
+    }
+
+    return sanitized;
+}
